local SeedDrillPlowMaker = {}
local PRODUCTS = {
    iron_seeddrillplow = { name = "Železni sejalni plug", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni sejalni plug za vrtove." },
    bronze_seeddrillplow = { name = "Bronast sejalni plug", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast sejalni plug za vrtove." },
    silver_seeddrillplow = { name = "Srebrn sejalni plug", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn sejalni plug za vrtove." },
    gilded_seeddrillplow = { name = "Pozlačen sejalni plug", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen sejalni plug za vrtove." },
    jewel_set_seeddrillplow = { name = "Draguljast sejalni plug", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast sejalni plug za vrtove." },
    royal_sovereign_seeddrillplow = { name = "Kraljevski suveren sejalni plug", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren sejalni plug z biseri za krono." },
}
local BUILDINGS = {
    seeddrillplow_workshop = { name = "Seeddrillplow delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    seeddrillplow_house = { name = "Seeddrillplow hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_seeddrillplow_atelier = { name = "Mojstrski seeddrillplow atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_seeddrillplow_palace = { name = "Suverena seeddrillplow palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
SeedDrillPlowMaker.ironStock = 18; SeedDrillPlowMaker.bronzeStock = 14; SeedDrillPlowMaker.woodStock = 12; SeedDrillPlowMaker.leatherStock = 8; SeedDrillPlowMaker.silverStock = 8; SeedDrillPlowMaker.goldStock = 6; SeedDrillPlowMaker.jewelStock = 4; SeedDrillPlowMaker.pearlStock = 4
SeedDrillPlowMaker.productStock = {}; SeedDrillPlowMaker.buildings = {}; SeedDrillPlowMaker.maker = nil; SeedDrillPlowMaker.activeMaking = {}; SeedDrillPlowMaker.totalProducts = 0; SeedDrillPlowMaker.dayTimer = 0
function SeedDrillPlowMaker.init() SeedDrillPlowMaker.ironStock=18; SeedDrillPlowMaker.bronzeStock=14; SeedDrillPlowMaker.woodStock=12; SeedDrillPlowMaker.leatherStock=8; SeedDrillPlowMaker.silverStock=8; SeedDrillPlowMaker.goldStock=6; SeedDrillPlowMaker.jewelStock=4; SeedDrillPlowMaker.pearlStock=4; SeedDrillPlowMaker.productStock={}; SeedDrillPlowMaker.buildings={}; SeedDrillPlowMaker.maker=nil; SeedDrillPlowMaker.activeMaking={}; SeedDrillPlowMaker.totalProducts=0; SeedDrillPlowMaker.dayTimer=0; print("[SeedDrillPlowMaker] Royal Seed Drill Plow Maker System initialized (6 products, 4 buildings)") end
function SeedDrillPlowMaker.hireMaker(n,s) s=s or math.random(55,90); local c=590+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SeedDrillPlowMaker.maker={name=n or ("Vlekar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vlekar najet: %s (spretnost: %d)",SeedDrillPlowMaker.maker.name,s),"success") end; return true end
function SeedDrillPlowMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SeedDrillPlowMaker.build(id) local ok,e=SeedDrillPlowMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SeedDrillPlowMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SeedDrillPlowMaker.getQualityBonus() local b=0; for _,bd in ipairs(SeedDrillPlowMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SeedDrillPlowMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SeedDrillPlowMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SeedDrillPlowMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SeedDrillPlowMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SeedDrillPlowMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SeedDrillPlowMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SeedDrillPlowMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SeedDrillPlowMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SeedDrillPlowMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SeedDrillPlowMaker.buildings==0 then return false,"Potrebna vlečna delavnica" end; if not SeedDrillPlowMaker.maker then return false,"Potreben vlekar" end; return true end
function SeedDrillPlowMaker.make(pt,qty) qty=qty or 1; local ok,e=SeedDrillPlowMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SeedDrillPlowMaker.ironStock=SeedDrillPlowMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SeedDrillPlowMaker.bronzeStock=SeedDrillPlowMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SeedDrillPlowMaker.woodStock=SeedDrillPlowMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SeedDrillPlowMaker.leatherStock=SeedDrillPlowMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SeedDrillPlowMaker.silverStock=SeedDrillPlowMaker.silverStock-d.silverCost*qty end; if d.goldCost then SeedDrillPlowMaker.goldStock=SeedDrillPlowMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SeedDrillPlowMaker.jewelStock=SeedDrillPlowMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SeedDrillPlowMaker.pearlStock=SeedDrillPlowMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SeedDrillPlowMaker.maker then t=math.max(1,t-math.floor(SeedDrillPlowMaker.maker.skill/13)) end; table.insert(SeedDrillPlowMaker.activeMaking,{id="seeddrillplow_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SeedDrillPlowMaker.completeMaking(m) local q=1.0+(SeedDrillPlowMaker.getQualityBonus()/100); if SeedDrillPlowMaker.maker then q=q+(SeedDrillPlowMaker.maker.skill/140) end; q=math.min(2.5,q); SeedDrillPlowMaker.productStock[m.productType]=(SeedDrillPlowMaker.productStock[m.productType] or 0)+m.quantity; SeedDrillPlowMaker.totalProducts=SeedDrillPlowMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SeedDrillPlowMaker.maker then SeedDrillPlowMaker.maker.itemsMade=SeedDrillPlowMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SeedDrillPlowMaker.maker.skill=math.min(100,SeedDrillPlowMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pflug izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"seeddrillplow.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function SeedDrillPlowMaker.update(dt) if not _G.state then return end; SeedDrillPlowMaker.dayTimer=SeedDrillPlowMaker.dayTimer+dt; if SeedDrillPlowMaker.dayTimer>=30 then SeedDrillPlowMaker.dayTimer=0; for i=#SeedDrillPlowMaker.activeMaking,1,-1 do local m=SeedDrillPlowMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SeedDrillPlowMaker.completeMaking(m); table.remove(SeedDrillPlowMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SeedDrillPlowMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SeedDrillPlowMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SeedDrillPlowMaker.getStats() return {ironStock=SeedDrillPlowMaker.ironStock,bronzeStock=SeedDrillPlowMaker.bronzeStock,woodStock=SeedDrillPlowMaker.woodStock,leatherStock=SeedDrillPlowMaker.leatherStock,silverStock=SeedDrillPlowMaker.silverStock,goldStock=SeedDrillPlowMaker.goldStock,jewelStock=SeedDrillPlowMaker.jewelStock,pearlStock=SeedDrillPlowMaker.pearlStock,productStock=SeedDrillPlowMaker.productStock,numBuildings=#SeedDrillPlowMaker.buildings,hasMaker=SeedDrillPlowMaker.maker~=nil,makerName=SeedDrillPlowMaker.maker and SeedDrillPlowMaker.maker.name or "—",makerSkill=SeedDrillPlowMaker.maker and SeedDrillPlowMaker.maker.skill or 0,activeMaking=#SeedDrillPlowMaker.activeMaking,totalProducts=SeedDrillPlowMaker.totalProducts} end
return SeedDrillPlowMaker
